import { extname } from 'path';

/**
 * File ownership (plan 5 P3.0): Generator-owned files start with the
 * `// Auto Generated By Generator - …` header. Anything else is user-owned and is never overwritten —
 * neither by backend generation nor by saving a model from the Generator UI.
 */
const GENERATOR_HEADER = /^\s*\/\/ Auto Generated By Generator\b/;

export function isGeneratorOwnedSource(content: string): boolean {
  return GENERATOR_HEADER.test(content);
}

export const USER_OWNED_FILE_MESSAGE =
  'Bu dosya Generator tarafından üretilmemiş (Generator başlığı yok); elle yazılmış dosyanın üzerine yazılmaz.';

const LINE_COMMENT: Record<string, string> = { '.ts': '//', '.tsx': '//', '.js': '//', '.jsx': '//', '.mjs': '//', '.cjs': '//', '.cs': '//', '.py': '#' };
const HAS_GENERATOR_HEADER = /^\s*(\/\/|#) (Auto )?Generated By Generator\b|^\s*\/\/ <auto-generated/;

function headerDate(date: Date): string {
  const pad = (n: number) => String(n).padStart(2, '0');
  return `${pad(date.getDate())}.${pad(date.getMonth() + 1)}.${date.getFullYear()} ${pad(date.getHours())}:${pad(date.getMinutes())}:${pad(date.getSeconds())}`;
}

function addHeader(path: string, content: string, header: string): string {
  const prefix = LINE_COMMENT[extname(path)];
  if (!prefix || content.startsWith('#!') || HAS_GENERATOR_HEADER.test(content)) return content;
  return `${prefix} ${header}\n${content}`;
}

/** "Auto" ile başlamadığı için projeye ait sayılır. */
export const withOnceHeader = (path: string, content: string, now = new Date()): string =>
  addHeader(path, content, `Generated By Generator - ${headerDate(now)} (bir kez yazıldı)`);

export const withSharedHeader = (path: string, content: string, now = new Date()): string =>
  addHeader(path, content, `Auto Generated By Generator - ${headerDate(now)}`);

/** Karşılaştırma için baştaki Generator başlık satırını atar (tarih her yazışta değişir). */
export const withoutGeneratorHeader = (content: string): string =>
  content.replace(/^\s*(\/\/|#) (Auto )?Generated By Generator\b[^\n]*\n/, '');
